--
-- Name: transitive_subclassof; Type: MATERIALIZED VIEW; Schema: public; Owner: jovyan
--

CREATE MATERIALIZED VIEW public.transitive_subclassof AS
 WITH RECURSIVE t_ontology(subject, object, hops, path) AS (
         SELECT DISTINCT o.subject,
            o.object,
            1 AS "?column?",
            ARRAY[o.subject, o.object] AS "array"
           FROM public.ontology o
          WHERE (o.predicate = 'http://www.w3.org/2000/01/rdf-schema#subClassOf'::text)
        UNION
         SELECT DISTINCT o.subject,
            t.object,
            (t.hops + 1),
            (o.subject || t.path)
           FROM (public.ontology o
             JOIN t_ontology t ON ((o.object = t.subject)))
          WHERE (o.predicate = 'http://www.w3.org/2000/01/rdf-schema#subClassOf'::text)
        )
 SELECT t_ontology.object,
    t_ontology.subject,
    t_ontology.hops,
    t_ontology.path
   FROM t_ontology
  WITH NO DATA;


ALTER TABLE public.transitive_subclassof OWNER TO jovyan;

